INSERT INTO recipe_unmatched_ingredient (recipe_unmatched_ingredient_recipe_id, recipe_unmatched_ingredient_line_no, recipe_unmatched_ingredient_raw_text, recipe_unmatched_ingredient_reason) SELECT 1, 3, '50 g Speck', 'unmatched' FROM DUAL WHERE EXISTS (SELECT 1 FROM recipe WHERE recipe_id = 1) AND NOT EXISTS (SELECT 1 FROM recipe_unmatched_ingredient WHERE recipe_unmatched_ingredient_recipe_id = 1 AND recipe_unmatched_ingredient_line_no <=> 3 AND BINARY recipe_unmatched_ingredient_raw_text = '50 g Speck' AND recipe_unmatched_ingredient_reason = 'unmatched');
